    },
    {
      "card_ids": ["C12"],
      "claim": "A related fused heterocycle containing a tertiary amine and methoxy groups achieved a rat brain/plasma Kp of 3.4 after IV dosing, showing that basic nitrogen in this structural family does not prevent meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A methoxyphenylethyl chromone was detected across multiple rat brain regions by DESI-MSI, supporting brain penetration of lipophilic methoxy-substituted chromone/coumarin structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "α-Allocryptopine, a fused alkaloid with a tertiary amine, was detected in rat CSF, indicating that basic amine-containing fused heterocycles can still cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Warfarin, a 4-hydroxycoumarin, showed moderate BBB permeability in the in situ rat brain perfusion model, providing direct experimental evidence that coumarin derivatives can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: the query is a lipophilic, low-TPSA methoxy-coumarin fused with a tertiary amine; multiple high-transfer experimental analogues from coumarin/chromone families demonstrate brain/CSF penetration, and the physicochemical prior supports passive diffusion. No strong contradictory evidence was identified.",
